function reindex(id) {
  const b = db.prepare('SELECT * FROM bookmarks WHERE id = ?').get(id);
  delFts.run(id);
  if (!b) return;
  insFts.run(id, b.title, b.description, b.notes, b.url, getTags(id).join(' '));
