  return {
    ...b,
    favorite: !!b.favorite,
    read_later: !!b.read_later,
    archived: !!b.archived,
    tags: getTags(b.id),
    snapshot_url: b.snapshot_path ? '/' + b.snapshot_path.replace(/\\/g, '/') : '',
  };
}

const SORTS = {
  created_desc: 'b.created_at DESC, b.id DESC',
  created_asc: 'b.created_at ASC, b.id ASC',
