// Translate a user search string into FTS5 MATCH expressions.
//
// Supported syntax:
//   "exact phrase"        -> matched as an exact phrase
//   foo bar               -> implicit AND
//   foo AND bar           -> both required
//   foo OR bar            -> either
//   foo NOT bar / -bar    -> exclude bar (global exclusion)
//
// Returns { positive, negative } FTS5 expressions (either may be '').
// The caller matches on `positive` (or all rows when empty) and subtracts
// rows matching `negative`.

function tokenize(input) {
  const tokens = [];
  const re = /"([^"]*)"|(\S+)/g;
  let m;
  while ((m = re.exec(input)) !== null) {
    if (m[1] !== undefined) {
      tokens.push({ type: 'phrase', value: m[1] });
    } else {
      const w = m[2];
      const upper = w.toUpperCase();
      if (upper === 'AND' || upper === 'OR' || upper === 'NOT') {
        tokens.push({ type: 'op', value: upper });
      } else {
        tokens.push({ type: 'word', value: w });
      }
    }
  }
  return tokens;
}

// Escape a term/phrase for FTS5: wrap in double quotes so punctuation, URLs
// and reserved words are treated literally as a phrase.
function ftsQuote(value) {
  const cleaned = value.replace(/"/g, ' ').trim();
  return cleaned ? `"${cleaned}"` : '';
}

export function parseQuery(input) {
  if (!input || !input.trim()) return { positive: '', negative: '' };
  const tokens = tokenize(input);
  const positives = []; // { connector, term }
  const negatives = [];
  let connector = 'AND';
  let negateNext = false;

  for (const tok of tokens) {
    if (tok.type === 'op') {
      if (tok.value === 'NOT') negateNext = true;
      else connector = tok.value;
      continue;
    }
    let value = tok.value;
    let negate = negateNext;
    negateNext = false;
    if (tok.type === 'word' && value.startsWith('-') && value.length > 1) {
      negate = true;
      value = value.slice(1);
    }
    const term = ftsQuote(value);
    if (!term) continue;
    if (negate) {
      negatives.push(term);
    } else {
      positives.push({ connector: positives.length ? connector : null, term });
    }
    connector = 'AND';
  }

  const positive = positives
    .map((p, i) => (i === 0 ? p.term : `${p.connector} ${p.term}`))
    .join(' ');
  const negative = negatives.join(' OR ');
  return { positive, negative };
}
import * as cheerio from 'cheerio';
import { writeFile } from 'fs/promises';
import { join } from 'path';
import { SNAPSHOT_DIR } from '../db.js';

const UA =
  'Mozilla/5.0 (compatible; BookmarkManager/1.0; +local)';

function absUrl(href, base) {
  if (!href) return '';
  try {
    return new URL(href, base).href;
  } catch {
    return '';
  }
}

async function fetchWithTimeout(url, ms = 9000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), ms);
  try {
    const res = await fetch(url, {
      headers: { 'user-agent': UA, accept: 'text/html,*/*' },
      redirect: 'follow',
      signal: controller.signal,
    });
    return res;
  } finally {
    clearTimeout(timer);
  }
}

// Best-effort. Never throws; returns whatever it managed to extract plus the
// raw HTML (for snapshotting) and an `ok`/`error` status.
export async function fetchMetadata(url) {
  const result = {
    ok: false,
    error: '',
    title: '',
    description: '',
    favicon: '',
    preview_image: '',
    html: '',
    finalUrl: url,
  };
  try {
    const res = await fetchWithTimeout(url);
    result.finalUrl = res.url || url;
    if (!res.ok) {
      result.error = `HTTP ${res.status}`;
    }
    const type = res.headers.get('content-type') || '';
    if (!type.includes('html')) {
      result.error = result.error || `Not HTML (${type || 'unknown'})`;
      result.ok = true; // reachable, just nothing to parse
      return result;
    }
    const html = await res.text();
    result.html = html;
    const $ = cheerio.load(html);
    const base = result.finalUrl;

    const pick = (...sels) => {
      for (const sel of sels) {
        const el = $(sel).first();
        const v = (el.attr('content') || el.text() || '').trim();
        if (v) return v;
      }
      return '';
    };

    result.title = pick(
      'meta[property="og:title"]',
      'meta[name="twitter:title"]',
      'title'
    );
    result.description = pick(
      'meta[property="og:description"]',
      'meta[name="description"]',
      'meta[name="twitter:description"]'
    );
    const img = pick('meta[property="og:image"]', 'meta[name="twitter:image"]');
    result.preview_image = absUrl(img, base);

    let icon =
      $('link[rel~="icon"]').first().attr('href') ||
      $('link[rel="shortcut icon"]').first().attr('href') ||
      $('link[rel="apple-touch-icon"]').first().attr('href') ||
      '';
    if (!icon) icon = '/favicon.ico';
    result.favicon = absUrl(icon, base);

    result.ok = true;
    return result;
  } catch (err) {
    result.error = err.name === 'AbortError' ? 'Timed out' : err.message;
    return result;
  }
}

// Save a local single-file snapshot of the page HTML. Adds a <base> tag so the
// browser resolves relative assets/links against the original site.
export async function saveSnapshot(id, html, finalUrl) {
  if (!html) return '';
  let doc = html;
  const baseTag = `<base href="${finalUrl.replace(/"/g, '&quot;')}">`;
  if (/<head[^>]*>/i.test(doc)) {
    doc = doc.replace(/<head([^>]*)>/i, `<head$1>${baseTag}`);
  } else {
    doc = baseTag + doc;
  }
  const banner =
    `<div style="position:sticky;top:0;z-index:2147483647;background:#1f2937;` +
    `color:#fff;font:13px system-ui,sans-serif;padding:6px 12px">` +
    `Local snapshot &middot; original: ` +
    `<a href="${finalUrl.replace(/"/g, '&quot;')}" style="color:#93c5fd">${finalUrl.replace(/</g, '&lt;')}</a></div>`;
  if (/<body[^>]*>/i.test(doc)) {
    doc = doc.replace(/<body([^>]*)>/i, `<body$1>${banner}`);
  } else {
    doc = banner + doc;
  }
  const rel = join('snapshots', `${id}.html`);
  await writeFile(join(SNAPSHOT_DIR, `${id}.html`), doc, 'utf8');
  return rel;
}
import * as cheerio from 'cheerio';

// Parse a standard Netscape bookmark file (Chrome/Firefox/Safari export).
// Returns [{ url, title, description, tags, created_at }]. Enclosing folder
// names (H3) become tags, plus any explicit TAGS="a,b" attribute (Firefox).
export function parseNetscape(html) {
  const $ = cheerio.load(html);
  const items = [];

  $('a').each((_, el) => {
    const a = $(el);
    const url = (a.attr('href') || '').trim();
    if (!url || /^(place:|javascript:)/i.test(url)) return;

    const title = a.text().trim() || url;
    const tags = new Set();

    const attrTags = a.attr('tags');
    if (attrTags) attrTags.split(',').forEach((t) => t.trim() && tags.add(t.trim()));

    // Walk up folder structure: each enclosing <DL> is preceded by an <H3>.
    let node = a.closest('dl');
    while (node.length) {
      const h3 = node.prevAll('h3').first();
      const name = h3.text().trim();
      if (name && !/^(bookmarks(\s+(bar|menu|toolbar))?|bookmarks)$/i.test(name)) {
        tags.add(name);
      }
      node = node.parent().closest('dl');
    }

    const dd = a.closest('dt').next('dd');
    const description = dd.length ? dd.text().trim() : '';

    const addDate = a.attr('add_date');
    let created_at = '';
    if (addDate && /^\d+$/.test(addDate)) {
      const d = new Date(parseInt(addDate, 10) * 1000);
      if (!isNaN(d.getTime())) created_at = d.toISOString().slice(0, 19).replace('T', ' ');
    }

    items.push({ url, title, description, tags: [...tags], created_at });
  });

  return items;
}

function esc(s) {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// Produce a standard Netscape bookmark file from bookmark rows (each with a
// `tags` array). Re-importable by any browser; tags stored in TAGS="".
export function exportNetscape(rows) {
  const lines = [
    '<!DOCTYPE NETSCAPE-Bookmark-file-1>',
    '<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">',
    '<TITLE>Bookmarks</TITLE>',
    '<H1>Bookmarks</H1>',
    '<DL><p>',
  ];
  for (const b of rows) {
    const ts = b.created_at
      ? Math.floor(new Date(b.created_at.replace(' ', 'T') + 'Z').getTime() / 1000)
      : '';
    const attrs = [`HREF="${esc(b.url)}"`];
    if (ts) attrs.push(`ADD_DATE="${ts}"`);
    if (b.tags && b.tags.length) attrs.push(`TAGS="${esc(b.tags.join(','))}"`);
    lines.push(`    <DT><A ${attrs.join(' ')}>${esc(b.title || b.url)}</A>`);
    if (b.description) lines.push(`    <DD>${esc(b.description)}`);
  }
  lines.push('</DL><p>');
  return lines.join('\n');
}
